const KEY="medibook_classic_plus_v1";
const today=()=>new Date().toISOString().slice(0,10);
const DEFAULT_STATE={bookings:[],ratings:[],favorites:[],settings:{theme:"dark",compact:false,sound:false,location:"Chennai"},labs:[],labOrders:[],medicines:[],medicineReminders:[],surgeries:[],cases:[],selectedHospital:"h1",onboarded:false,profile:{},medicineCatalog:[]};
let state;
try{state=JSON.parse(localStorage.getItem(KEY)||"null");}catch(e){state=null;try{localStorage.removeItem(KEY)}catch(_){} }
state=state&&typeof state==="object"?state:{};
state.bookings=Array.isArray(state.bookings)?state.bookings:[];
state.ratings=Array.isArray(state.ratings)?state.ratings:[];
state.favorites=Array.isArray(state.favorites)?state.favorites:[];
state.labs=Array.isArray(state.labs)?state.labs:[];
state.labOrders=Array.isArray(state.labOrders)?state.labOrders:state.labs;
state.medicines=Array.isArray(state.medicines)?state.medicines:[];
state.medicineReminders=Array.isArray(state.medicineReminders)?state.medicineReminders:[];
state.surgeries=Array.isArray(state.surgeries)?state.surgeries:[];
state.cases=Array.isArray(state.cases)?state.cases:[];
state.profile=state.profile&&typeof state.profile==="object"?state.profile:{};
state.settings={...DEFAULT_STATE.settings,...(state.settings&&typeof state.settings==="object"?state.settings:{})};
state.selectedHospital=state.selectedHospital||({Chennai:"h1",Adyar:"h1","Anna Nagar":"h2",Guindy:"h3",Nungambakkam:"h4"}[state.settings.location]||"h1");
state.onboarded=Boolean(state.onboarded);
state.medicineCatalog=Array.isArray(state.medicineCatalog)&&state.medicineCatalog.length?state.medicineCatalog:MEDICINES.map(x=>({...x,available:true}));
state.bookings=state.bookings.filter(a=>a&&doctors.some(d=>d.id===a.doctorId));
state.ratings=state.ratings.filter(r=>r&&doctors.some(d=>d.id===r.doctorId));
let selectedDoctor=null,selectedDate="",selectedSlot="",selectedMode="In-person",selectedHospital="h1",selectedPayment="UPI / Demo",bookingStep=1,favOnly=false,activeSpecialty="All";
const save=()=>localStorage.setItem(KEY,JSON.stringify(state));
const esc=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[m]));
const toast=t=>{const e=document.getElementById("toast");e.textContent=t;e.classList.add("show");setTimeout(()=>e.classList.remove("show"),2800)};
const initials=n=>n.split(" ").filter(Boolean).slice(1,3).map(x=>x[0]).join("");
const avatar=d=>`<div class="avatar" style="display:grid;place-items:center;font-weight:800;color:#06121e;background:linear-gradient(135deg,${d.color},#fff)">${initials(d.name)}</div>`;
const stars=r=>"★★★★★".split("").map((s,i)=>i<Math.round(r)?s:"☆").join("");
const doctorRating=d=>{const rs=state.ratings.filter(r=>r.doctorId===d.id);return rs.length?rs.reduce((a,b)=>a+b.value,0)/rs.length:d.rating};
const doctorById=id=>doctors.find(d=>d.id===id);
const fmtDate=x=>x?new Date(x+"T00:00:00").toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric"}):"";
const money=n=>`₹${Number(n).toLocaleString("en-IN")}`;
const LOCATION_HOSPITALS={Chennai:"h1",Adyar:"h1","Anna Nagar":"h2",Guindy:"h3",Nungambakkam:"h4"};
const hospitalForLocation=loc=>LOCATION_HOSPITALS[loc]||"h1";
function renderSpecialties(id){
  const el=document.getElementById(id);
  if(!el)return;
  if(id==="homeSpecialties"){
    el.className="specialty-gallery";
    el.innerHTML=SPECIALTIES.map(s=>`<button class="specialty-card ${activeSpecialty===s.value?"active":""}" data-specialty="${esc(s.value)}">
      <div class="specialty-image-wrap"><img src="${esc(s.image)}" alt="${esc(s.name)} specialty" loading="lazy"></div>
      <div class="specialty-card-body"><div class="specialty-icon">${s.icon}</div><div><b>${esc(s.name)}</b><small>${esc(s.description)}</small></div></div>
    </button>`).join("");
  }else{
    el.className="strip specialty-chip-strip";
    el.innerHTML=`<button class="chip specialty-chip all-chip ${activeSpecialty==="All"?"active":""}" data-specialty="All"><span class="chip-image chip-image-fallback">✦</span><span>All specialties</span></button>`+
      SPECIALTIES.map(s=>`<button class="chip specialty-chip ${activeSpecialty===s.value?"active":""}" data-specialty="${esc(s.value)}"><img class="chip-image" src="${esc(s.image)}" alt="${esc(s.name)}" loading="lazy"><span>${s.icon} ${esc(s.name)}</span></button>`).join("");
  }
}
function doctorCard(d){const r=doctorRating(d),fav=state.favorites.includes(d.id);return `<article class="card reveal"><div class="doctor-top">${avatar(d)}<div style="flex:1"><div class="doctor-name">${esc(d.name)}</div><div class="muted">${esc(d.qualification)}</div><div class="stars">${stars(r)} <span class="muted">${r.toFixed(1)} · ${d.reviews} reviews</span></div></div><button class="icon-btn heart" data-fav="${d.id}">${fav?"♥":"♡"}</button></div><div class="doctor-meta"><span class="tag">${esc(d.specialty)}</span><span class="tag">${d.experience} yrs exp.</span><span class="tag">${money(d.fee)}</span><span class="tag">${d.availableToday?"● Available today":"○ Not available today"}</span></div><div class="muted">${d.consultationModes.join(" & ")} • ${esc(d.location)}</div><div class="muted" style="margin-top:8px">${d.symptoms.slice(0,4).map(esc).join(" · ")}</div><div class="card-actions"><button class="btn primary magnetic" data-book="${d.id}">Book now</button><button class="btn" data-profile="${d.id}">Profile</button></div></article>`}
function renderDoctors(){const q=(document.getElementById("search")?.value||"").toLowerCase();let list=doctors.filter(d=>(activeSpecialty==="All"||d.specialty===activeSpecialty)&&[d.name,d.qualification,d.specialty,...d.symptoms].join(" ").toLowerCase().includes(q));if(favOnly)list=list.filter(d=>state.favorites.includes(d.id));const grid=document.getElementById("doctorGrid");if(!grid)return;grid.innerHTML=list.length?list.map(doctorCard).join(""):`<div class="empty" style="grid-column:1/-1">No doctors found. Try another specialty or search.</div>`;bindDoctorActions();if(window.gsap){gsap.utils.toArray(".reveal").forEach(el=>gsap.fromTo(el,{opacity:0,y:18},{opacity:1,y:0,duration:.45,delay:.03,overwrite:true}))}}
function bindDoctorActions(){document.querySelectorAll("[data-book]").forEach(b=>b.onclick=()=>openBooking(b.dataset.book));document.querySelectorAll("[data-fav]").forEach(b=>b.onclick=()=>{const id=b.dataset.fav;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();renderDoctors();toast(state.favorites.includes(id)?"Saved to favorites":"Removed from favorites")});document.querySelectorAll("[data-profile]").forEach(b=>b.onclick=()=>{const d=doctorById(b.dataset.profile);openServiceModal(`${d.name} — profile`, `<div class="summary">${avatar(d)}<h3>${esc(d.name)}</h3><p class="muted">${esc(d.qualification)} · ${d.experience} years experience</p><div class="stars">${stars(doctorRating(d))} ${doctorRating(d).toFixed(1)} · ${d.reviews} reviews</div><p>${esc(d.bio)}</p><div class="pill-row">${d.symptoms.map(x=>`<span class="tag">${esc(x)}</span>`).join("")}</div><p class="muted" style="margin-top:15px">Fee: <b class="fee">${money(d.fee)}</b> · Modes: ${d.consultationModes.join(", ")}</p></div><div class="actions"><button class="btn primary" data-modal-book="${d.id}">Book with ${esc(d.name)}</button></div>`)});}
function renderAppointments(){const list=document.getElementById("appointmentList");if(!list)return;const arr=[...state.bookings].sort((a,b)=>(a.date+a.slot).localeCompare(b.date+b.slot));if(!arr.length){list.innerHTML='<div class="card empty">No appointments yet.<br><br><button class="btn primary" data-view="doctors">Find a doctor</button></div>';return}list.innerHTML=arr.map(a=>{const d=doctorById(a.doctorId);return `<div class="card appointment"><div style="display:flex;gap:15px;align-items:center">${avatar(d)}<div><b>${d.name}</b><div class="muted">${d.specialty} • ${fmtDate(a.date)} • ${a.slot}</div><small class="muted">Booking ID: ${a.id} · ${a.mode||"In-person"}${a.hospitalName?` · ${esc(a.hospitalName)}`:""}</small><div class="pill-row" style="margin-top:6px"><span class="tag">${money(d.fee)}</span>${a.paymentStatus?`<span class="tag">${a.paymentStatus}</span>`:""}</div></div></div><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;justify-content:flex-end"><span class="status ${a.status==="cancelled"?"cancelled":""}">${a.status}</span>${a.status==="confirmed"?`<button class="btn" data-reschedule="${a.id}">Reschedule</button><button class="btn" data-cancel="${a.id}">Cancel</button>`:""}${a.status==="completed"&&!a.rating?`<button class="btn primary" data-rate="${a.id}">Rate</button>`:""}${a.status!=="cancelled"?`<button class="btn" data-pdf="${a.id}">PDF / Bill</button>`:""}</div></div>`}).join("");list.querySelectorAll("[data-cancel]").forEach(b=>b.onclick=()=>{const a=state.bookings.find(x=>x.id===b.dataset.cancel);if(a){a.status="cancelled";save();renderAll();toast("Appointment cancelled")}});list.querySelectorAll("[data-reschedule]").forEach(b=>{const a=state.bookings.find(x=>x.id===b.dataset.reschedule);openBooking(a.doctorId,a)});list.querySelectorAll("[data-rate]").forEach(b=>{const a=state.bookings.find(x=>x.id===b.dataset.rate),v=prompt("Rate your completed appointment (1–5 stars):","5"),n=Number(v);if(n>=1&&n<=5){a.rating=n;state.ratings.push({doctorId:a.doctorId,value:n,bookingId:a.id});save();renderAll();toast("Thank you — rating saved")}});list.querySelectorAll("[data-pdf]").forEach(b=>b.onclick=()=>downloadPDF(b.dataset.pdf))}
function renderRecords(){const completed=state.bookings.filter(x=>x.status==="completed").length,cancelled=state.bookings.filter(x=>x.status==="cancelled").length,confirmed=state.bookings.filter(x=>x.status==="confirmed").length;document.getElementById("recordStats").innerHTML=[["Total bookings",state.bookings.length],["Upcoming",confirmed],["Completed",completed],["Cancelled",cancelled]].map(x=>`<div class="card stat"><b>${x[1]}</b><small>${x[0]}</small></div>`).join("");document.getElementById("recordList").innerHTML=state.bookings.length?state.bookings.map(a=>{const d=doctorById(a.doctorId);return `<div class="card appointment"><div><b>${d.name}</b><div class="muted">${d.specialty} • ${fmtDate(a.date)} • ${a.slot}</div><small class="muted">${a.id} · ${a.status}</small></div><span class="status">${a.status}</span></div>`}).join(""):'<div class="card empty">Your appointment history will appear here.</div>'}
function renderDoctorView(){const confirmed=state.bookings.filter(a=>a.status==="confirmed").length,completed=state.bookings.filter(a=>a.status==="completed").length;document.getElementById("doctorStats").innerHTML=[["Patients",new Set(state.bookings.map(a=>a.patientName)).size],["Scheduled",confirmed],["Completed",completed],["Reviews",state.ratings.length]].map(x=>`<div class="card stat"><b>${x[1]}</b><small>${x[0]}</small></div>`).join("");document.getElementById("doctorBookings").innerHTML=state.bookings.length?`<div class="actions" style="margin-bottom:14px">${confirmed?`<button class="btn primary" id="doctorUnavailable">Doctor unavailable</button>`:""}</div>`+state.bookings.map(a=>{const d=doctorById(a.doctorId);return `<div class="card appointment"><div><b>${esc(a.patientName||"Patient")}</b><div class="muted">${d.name} • ${d.specialty} • ${fmtDate(a.date)} • ${a.slot}</div><small class="muted">${a.id} • ${esc(a.phone||"")} • ${a.mode||"In-person"}</small></div><div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end"><span class="status ${a.status==="cancelled"?"cancelled":""}">${a.status}</span>${a.status==="confirmed"?`<button class="btn" data-complete="${a.id}">Mark completed</button>`:""}<button class="btn" data-handover="${a.id}">Handover summary</button></div></div>`}).join(""):'<div class="card empty">No patient bookings yet.</div>';document.querySelectorAll("[data-complete]").forEach(b=>b.onclick=()=>{const a=state.bookings.find(x=>x.id===b.dataset.complete);a.status="completed";save();renderAll();toast("Appointment marked completed")});document.querySelectorAll("[data-handover]").forEach(b=>b.onclick=()=>openHandover(b.dataset.handover));const unavailable=document.getElementById("doctorUnavailable");if(unavailable)unavailable.onclick=()=>openDoctorUnavailable()}
function openDoctorUnavailable(){const confirmed=state.bookings.filter(a=>a.status==="confirmed");const byDoctor={};confirmed.forEach(a=>{const d=doctorById(a.doctorId);if(d)byDoctor[d.id]=d});const doctorsList=Object.values(byDoctor);openServiceModal("Doctor unavailable",`<p class="muted">Choose what should happen to the accepted appointments.</p><div class="mini-grid"><button class="payment-option" id="rescheduleAll"><b>Option 1 — Reschedule all</b><br><span class="muted">Move patients to available slots on another date.</span></button><button class="payment-option" id="transferAll"><b>Option 2 — Transfer to another doctor</b><br><span class="muted">Offer the appointments to another doctor in the same specialty.</span></button><button class="payment-option" id="cancelAll"><b>Option 3 — Cancel appointments</b><br><span class="muted">Cancel the accepted appointments and notify patients.</span></button></div>`);document.getElementById("rescheduleAll").onclick=()=>rescheduleDoctorAppointments(confirmed);document.getElementById("transferAll").onclick=()=>transferDoctorAppointments(confirmed,doctorsList);document.getElementById("cancelAll").onclick=()=>{confirmed.forEach(a=>a.status="cancelled");save();document.getElementById("serviceModal").classList.remove("show");renderAll();toast(`${confirmed.length} appointment${confirmed.length>1?"s":""} cancelled`)}}
function rescheduleDoctorAppointments(appointments){const date=prompt("New date (YYYY-MM-DD):",today());if(!date)return;const target=appointments[0]?doctorById(appointments[0].doctorId):null;if(!target)return;const occupied=state.bookings.filter(a=>a.doctorId===target.id&&a.date===date&&a.status!=="cancelled"&&!appointments.some(x=>x.id===a.id)).map(a=>a.slot);const free=target.slots.filter(s=>!occupied.includes(s));if(free.length<appointments.length){toast("Not enough available slots for all appointments");return}appointments.forEach((a,i)=>{a.date=date;a.slot=free[i]});save();document.getElementById("serviceModal").classList.remove("show");renderAll();toast("Appointments rescheduled")}
function transferDoctorAppointments(appointments,doctorsList){const source=appointments.length?doctorById(appointments[0].doctorId):null;if(!source)return;const alternatives=doctors.filter(d=>d.specialty===source.specialty&&d.id!==source.id&&d.availableToday);if(!alternatives.length){toast("No other available doctor is available in this specialty");return}const names=alternatives.map((d,i)=>`${i+1}. ${d.name}`).join("\n");const pick=Number(prompt(`Choose another ${source.specialty} doctor:\n${names}`,"1"));const target=alternatives[pick-1];if(!target)return;const moved=[];appointments.forEach(a=>{const free=target.slots.find(s=>!state.bookings.some(x=>x.doctorId===target.id&&x.date===a.date&&x.slot===s&&x.status!=="cancelled"));if(free){a.previousDoctorId=a.doctorId;a.doctorId=target.id;a.slot=free;moved.push(a)}});save();document.getElementById("serviceModal").classList.remove("show");renderAll();toast(`${moved.length} appointment${moved.length>1?"s":""} transferred`)}
function openHandover(id){const a=state.bookings.find(x=>x.id===id);if(!a)return;const currentDoctor=doctorById(a.doctorId),previousDoctor=doctorById(a.previousDoctorId||a.doctorId),caseFor=state.cases.find(c=>c.patient===a.patientName),events=caseFor?.events||[],handover=a.handover||{},value=(key,fallback)=>handover[key]||fallback;const diagnosis=value("diagnosis",caseFor?.title||"Not recorded"),medicines=value("medicines",events.find(e=>/treatment|prescrib/i.test(e.label||""))?.text||"Not recorded"),tests=value("tests","Not recorded"),treatment=value("treatment",events.find(e=>/treatment/i.test(e.label||""))?.text||"Not recorded"),recommendations=value("recommendations",events.find(e=>/follow-up|recommend/i.test(e.label||""))?.text||"Not recorded"),changes=value("changes",caseFor?.stage?`Current care stage: ${caseFor.stage}.`:(a.notes?`Current reason or symptoms: ${a.notes}.`:"Not recorded"));openServiceModal("Doctor Handover Summary",`<div class="summary"><h3 style="margin-top:0">${esc(a.patientName||"Patient")}</h3><p><b>Previous doctor:</b> ${esc(previousDoctor?.name||"Not recorded")}</p><p><b>Current doctor:</b> ${esc(currentDoctor?.name||"Not recorded")}</p><p><b>Previous consultation:</b> ${fmtDate(a.date)}</p><p><b>Specialty:</b> ${esc((previousDoctor||currentDoctor)?.specialty||"Not recorded")}</p></div><div class="form-grid"><div class="full"><label class="form-label">Diagnosis</label><input id="handoverDiagnosis" class="input" value="${esc(diagnosis)}"></div><div><label class="form-label">Medicines</label><textarea id="handoverMedicines" class="input profile-textarea">${esc(medicines)}</textarea></div><div><label class="form-label">Tests</label><textarea id="handoverTests" class="input profile-textarea">${esc(tests)}</textarea></div><div><label class="form-label">Treatment</label><textarea id="handoverTreatment" class="input profile-textarea">${esc(treatment)}</textarea></div><div><label class="form-label">Recommendations</label><textarea id="handoverRecommendations" class="input profile-textarea">${esc(recommendations)}</textarea></div><div class="full"><label class="form-label">What changed since last visit</label><textarea id="handoverChanges" class="input profile-textarea">${esc(changes)}</textarea></div></div><div class="actions"><button class="btn primary" id="saveHandover">Save handover summary</button>${caseFor?`<button class="btn" id="fullCareHistory">View Full Care History</button>`:""}</div>`);document.getElementById("saveHandover").onclick=()=>{a.handover={diagnosis:document.getElementById("handoverDiagnosis").value.trim(),medicines:document.getElementById("handoverMedicines").value.trim(),tests:document.getElementById("handoverTests").value.trim(),treatment:document.getElementById("handoverTreatment").value.trim(),recommendations:document.getElementById("handoverRecommendations").value.trim(),changes:document.getElementById("handoverChanges").value.trim()};save();toast("Handover summary saved")};const history=document.getElementById("fullCareHistory");if(history)history.onclick=()=>{document.getElementById("serviceModal").classList.remove("show");showView("lifecycle");renderLifecycle()}}
function openBooking(doctorId,existing=null){selectedDoctor=doctorById(doctorId);selectedDate=existing?.date||"";selectedSlot=existing?.slot||"";selectedMode=existing?.mode||"In-person";selectedHospital=existing?.hospitalId||state.selectedHospital||"h1";selectedPayment=existing?.paymentMethod||"UPI / Demo";bookingStep=1;const panel=document.getElementById("bookingPanel");if(!panel)return;panel.dataset.editId=existing?.id||"";panel.style.display="block";panel.innerHTML=`<div class="modal-head"><div><div class="eyebrow">Book with</div><h3>${esc(selectedDoctor.name)}</h3></div><button class="btn" id="closeBookingPanel">Close</button></div><div class="steps"><i class="step on"></i><i class="step"></i><i class="step"></i><i class="step"></i><i class="step"></i></div><div id="bookingBody"></div>`;document.getElementById("closeBookingPanel").onclick=()=>{panel.style.display="none";panel.innerHTML=""};renderBooking();panel.scrollIntoView({behavior:"smooth",block:"start"})}
function renderBooking(){const body=document.getElementById("bookingBody"),panel=document.getElementById("bookingPanel");if(!body||!panel)return;const editId=panel.dataset.editId||"";document.querySelectorAll("#bookingPanel .step").forEach((s,i)=>s.classList.toggle("on",i<bookingStep));if(bookingStep===1){body.innerHTML=`<label class="form-label">Choose date</label><input id="datePicker" class="input" type="date" min="${today()}" value="${selectedDate||today()}"><div class="actions"><button class="btn primary magnetic" id="nextDate">Continue →</button></div>`;document.getElementById("nextDate").onclick=()=>{selectedDate=document.getElementById("datePicker").value;if(!selectedDate)return toast("Please choose a date");bookingStep=2;renderBooking()}}else if(bookingStep===2){const locked=state.bookings.filter(a=>a.doctorId===selectedDoctor.id&&a.date===selectedDate&&a.status!=="cancelled"&&a.id!==editId).map(a=>a.slot);body.innerHTML=`<div class="muted">Choose a time on <b>${fmtDate(selectedDate)}</b>. Booked slots are locked locally.</div><div class="slots">${selectedDoctor.slots.map(s=>`<button class="slot ${selectedSlot===s?"selected":""}" ${locked.includes(s)?"disabled":""} data-slot="${esc(s)}">${esc(s)}${locked.includes(s)?" · Full":""}</button>`).join("")}</div><div class="actions"><button class="btn" id="back">← Back</button><button class="btn primary" id="nextSlot">Continue →</button></div>`;body.querySelectorAll("[data-slot]").forEach(b=>b.onclick=()=>{selectedSlot=b.dataset.slot;renderBooking()});document.getElementById("back").onclick=()=>{bookingStep=1;renderBooking()};document.getElementById("nextSlot").onclick=()=>{if(!selectedSlot)return toast("Choose a time slot");bookingStep=3;renderBooking()}}else if(bookingStep===3){const prof=state.profile||{};body.innerHTML=`<div class="form-grid"><div><label class="form-label">Patient name *</label><input id="pname" class="input" placeholder="Your full name" value="${esc(prof.name||"")}"></div><div><label class="form-label">Phone *</label><input id="phone" class="input" placeholder="10-digit phone" value="${esc(prof.phone||"")}"></div><div><label class="form-label">Consultation mode</label><select id="mode" class="input"><option>In-person</option><option>Video</option></select></div><div><label class="form-label">Hospital</label><select id="hospital" class="input">${HOSPITALS.map(h=>`<option value="${h.id}" ${selectedHospital===h.id?"selected":""}>${esc(h.name)} · ${esc(h.area)}</option>`).join("")}</select></div><div class="full"><label class="form-label">Reason / symptoms</label><input id="notes" class="input" placeholder="e.g. fever for 2 days, follow-up, checkup"></div></div><div class="summary"><b>${esc(selectedDoctor.name)}</b><br><span class="muted">${fmtDate(selectedDate)} • ${esc(selectedSlot)} • ${money(selectedDoctor.fee)}</span><br><span class="muted">In-person appointments use the selected hospital. Video consultations are online.</span></div><div class="actions"><button class="btn" id="back">← Back</button><button class="btn primary" id="nextPatient">Continue to payment →</button></div>`;document.getElementById("mode").value=selectedMode;document.getElementById("nextPatient").onclick=()=>{const name=document.getElementById("pname").value.trim(),phone=document.getElementById("phone").value.trim();if(!name)return toast("Patient name is required");if(!/^\d{10}$/.test(phone))return toast("Phone must be exactly 10 digits");selectedMode=document.getElementById("mode").value;selectedHospital=document.getElementById("hospital").value;window.bookingDraft={name,phone,notes:document.getElementById("notes").value.trim()};bookingStep=4;renderBooking()};document.getElementById("back").onclick=()=>{bookingStep=2;renderBooking()}}else if(bookingStep===4){body.innerHTML=`<h3>Secure demo payment</h3><p class="muted">No real card or UPI credentials are collected. Choose a payment method and confirm the local demo transaction.</p><div class="mini-grid">${["UPI / Demo","Card / Demo","Pay at hospital"].map(x=>`<button class="payment-option ${selectedPayment===x?"selected":""}" data-paymethod="${x}"><b>${x}</b><br><span class="muted">Payment simulation</span></button>`).join("")}</div><div class="summary"><b>Bill total</b><div style="font-size:2rem;color:var(--primary);font-weight:800">${money(selectedDoctor.fee)}</div><span class="muted">Doctor consultation fee</span></div><div class="actions"><button class="btn" id="back">← Back</button><button class="btn primary" id="payConfirm">Pay ${money(selectedDoctor.fee)} & confirm</button></div>`;body.querySelectorAll("[data-paymethod]").forEach(b=>b.onclick=()=>{selectedPayment=b.dataset.paymethod;renderBooking()});document.getElementById("back").onclick=()=>{bookingStep=3;renderBooking()};document.getElementById("payConfirm").onclick=()=>confirmBooking()}else{const a=state.bookings.find(x=>x.id===window.lastBookingId);body.innerHTML=`<div id="billContent" class="bill"><div style="font-size:2rem;font-weight:800;color:#168d76">MediBook</div><h3>Appointment Confirmation & Bill</h3><hr><p><b>Booking ID:</b> ${a.id}</p><p><b>Patient:</b> ${esc(a.patientName)}<br><b>Doctor:</b> ${esc(selectedDoctor.name)}<br><b>Specialty:</b> ${esc(selectedDoctor.specialty)}<br><b>Date:</b> ${fmtDate(a.date)}<br><b>Time:</b> ${esc(a.slot)}<br><b>Mode:</b> ${esc(a.mode)}<br><b>Hospital:</b> ${esc(a.hospitalName||"Online")}</p><hr><p><b>Payment method:</b> ${esc(a.paymentMethod)}</p><h2>${money(a.amount)}</h2><p style="color:#607087">Payment status: PAID</p></div><div class="actions"><button class="btn" id="pdfConfirm">Download PDF bill</button><button class="btn primary" id="done">Done</button></div>`;document.getElementById("pdfConfirm").onclick=()=>downloadPDF(a.id);document.getElementById("done").onclick=()=>{panel.style.display="none";panel.innerHTML="";showView("appointments")}}}

function confirmBooking(){const editId=document.getElementById("bookingPanel").dataset.editId,draft=window.bookingDraft||{};if(editId){const a=state.bookings.find(x=>x.id===editId);a.date=selectedDate;a.slot=selectedSlot;a.patientName=draft.name;a.phone=draft.phone;a.notes=draft.notes;a.mode=selectedMode;a.hospitalId=selectedHospital;a.hospitalName=selectedMode==="Video"?"Online":(HOSPITALS.find(h=>h.id===selectedHospital)?.name||"");a.paymentMethod=selectedPayment;a.status="confirmed";window.lastBookingId=a.id;toast("Appointment rescheduled")}else{let id;do{id=`MB-${new Date().getFullYear()}-${Math.random().toString(36).slice(2,8).toUpperCase()}`}while(state.bookings.some(a=>a.id===id));const h=HOSPITALS.find(x=>x.id===selectedHospital);const a={id,doctorId:selectedDoctor.id,date:selectedDate,slot:selectedSlot,patientName:draft.name,phone:draft.phone,notes:draft.notes,status:"confirmed",createdAt:new Date().toISOString(),mode:selectedMode,hospitalId:selectedHospital,hospitalName:selectedMode==="Video"?"Online":h?.name,paymentMethod:selectedPayment,paymentStatus:"PAID (demo)",amount:selectedDoctor.fee};state.bookings.push(a);window.lastBookingId=id;if(state.settings.sound)beep();toast("Appointment confirmed")};save();scheduleAppointmentReminder(state.bookings.find(x=>x.id===window.lastBookingId));bookingStep=5;renderBooking();renderAll()}
function beep(){const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=new C(),o=c.createOscillator(),g=c.createGain();o.frequency.value=660;g.gain.value=.04;o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.12)}
function slotToMinutes(s){const [hm,ap]=s.split(" "),[h,m]=hm.split(":").map(Number);let H=h%12+(ap==="PM"?12:0);return H*60+m}
function appointmentTimestamp(a){const mins=slotToMinutes(a.slot);const d=new Date(a.date+"T00:00:00");d.setHours(Math.floor(mins/60),mins%60,0,0);return d.getTime()}
function scheduleAppointmentReminder(a){if(!a||a.status!=="confirmed")return;const delay=appointmentTimestamp(a)-Date.now()-10*60*1000;if(delay>0&&delay<2147483647)setTimeout(()=>toast(`🔔 Reminder: Your appointment with ${a.doctorName||doctorById(a.doctorId).name} starts in 10 minutes.`),delay)}
function scheduleMedicineReminder(r){const [h,m]=r.time.split(":").map(Number),now=new Date(),next=new Date();next.setHours(h,m,0,0);if(next<=now)next.setDate(next.getDate()+1);const delay=next-now;if(delay>0&&delay<2147483647)setTimeout(()=>{toast(`💊 Time to take your prescribed medicine: ${r.name}.`);scheduleMedicineReminder(r)},delay)}
function downloadPDF(id){const a=state.bookings.find(x=>x.id===id);if(!a)return;const d=doctorById(a.doctorId);const el=document.createElement("div");el.style.cssText="padding:40px;font-family:Arial;background:white;color:#112033;width:700px";el.innerHTML=`<h1 style="color:#168d76">MediBook</h1><h2>Appointment Confirmation & Bill</h2><hr><p><b>Booking ID:</b> ${esc(a.id)}</p><p><b>Patient:</b> ${esc(a.patientName)}</p><p><b>Doctor:</b> ${esc(d.name)}</p><p><b>Specialty:</b> ${esc(d.specialty)}</p><p><b>Date:</b> ${esc(a.date)}</p><p><b>Time:</b> ${esc(a.slot)}</p><p><b>Mode:</b> ${esc(a.mode)}</p><p><b>Hospital:</b> ${esc(a.hospitalName||"Online")}</p><p><b>Payment:</b> ${esc(a.paymentMethod)} · ${esc(a.paymentStatus||"PAID (demo)")}</p><h2>${money(a.amount||d.fee)}</h2><p style="margin-top:50px;color:#667">Generated by MediBook</p>`;html2pdf().set({margin:10,filename:`${a.id}.pdf`,html2canvas:{scale:2},jsPDF:{format:"a4"}}).from(el).save()}
function showView(id){document.querySelectorAll(".view").forEach(v=>v.classList.toggle("active",v.id===id));document.querySelectorAll("[data-view]").forEach(b=>b.classList.toggle("active",b.dataset.view===id));if(id==="profile")renderProfile();window.scrollTo({top:0,behavior:"smooth"})}
function renderServices(){
  const loc=document.getElementById("locationSummary");if(!loc)return;
  const currentHospital=HOSPITALS.find(h=>h.id===state.selectedHospital)||HOSPITALS[0];
  loc.innerHTML=`<b>📍 Current location: ${esc(state.settings.location)}</b><br><span>Default hospital: <b>${esc(currentHospital.name)}</b>. Selecting a location automatically changes the default hospital; you can still choose another hospital below.</span>`;
  document.getElementById("hospitalGrid").innerHTML=HOSPITALS.map(h=>`<article class="card service-card"><div class="service-icon">🏥</div><h3>${esc(h.name)}</h3><div class="muted">${esc(h.area)}</div><p>${esc(h.description)}</p><div class="pill-row">${h.facilities.map(x=>`<span class="tag">${esc(x)}</span>`).join("")}</div><p class="muted">${esc(h.address)}</p><button class="btn ${state.selectedHospital===h.id?"primary":""}" data-hospital="${h.id}">${state.selectedHospital===h.id?"✓ Selected hospital":"Select hospital"}</button></article>`).join("");
  document.getElementById("labGrid").innerHTML=LAB_TESTS.map(x=>`<article class="card service-card"><span class="tag">${esc(x.category)}</span><div class="service-icon">🧪</div><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p><b class="fee">${money(x.price)}</b> <span class="muted">· ${esc(x.turnaround)}</span><div class="card-actions"><button class="btn primary" data-lab="${x.id}">Book test</button></div></article>`).join("");
  const meds=state.medicineCatalog.filter(x=>x.available!==false);
  document.getElementById("medicineGrid").innerHTML=`<div class="toolbar service-toolbar full-service-toolbar"><input id="medicineSearch" class="input" placeholder="Search medicines..." value="${esc(window.medicineSearch||"")}"><button class="btn" id="clearMedicineSearch">Clear</button><button class="btn" id="manageMedicines">Manage medicines</button></div><div id="medicineResults" class="medicine-results">${meds.map(x=>`<article class="card service-card medicine-card"><span class="tag">${esc(x.category)}</span><div class="service-icon">💊</div><h3>${esc(x.name)}</h3><p>${esc(x.pack)}</p><b class="fee">${money(x.price)}</b><div class="toolbar"><label class="form-label" style="margin:0">Quantity</label><select class="input medicine-qty" id="qty-${x.id}" style="min-width:90px"><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option><option>10</option></select></div><div class="card-actions"><button class="btn primary" data-med="${x.id}">Place order</button><button class="btn" data-medrem="${x.id}">Reminder</button></div></article>`).join("")}</div><div id="medicineOrderPanel" style="margin-top:18px"></div><div id="medicineManagePanel" style="margin-top:18px"></div>`;
  document.getElementById("surgeryGrid").innerHTML=SURGERIES.map(x=>`<article class="card service-card"><span class="tag">${esc(x.specialty)}</span><div class="service-icon">🏥</div><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p><b>${esc(x.starting)}</b><div class="card-actions"><button class="btn primary" data-surgery="${x.id}">Start planning</button></div></article>`).join("");
  document.getElementById("qaList").innerHTML=EXPERT_QA.map(x=>`<div style="padding:16px 0;border-bottom:1px solid var(--line)"><b>${esc(x.q)}</b><p class="muted">${esc(x.a)}</p></div>`).join("");
  bindServices();
  if(window.medicineSearch)filterMedicineCards(window.medicineSearch);
}
function filterMedicineCards(q){const term=(q||"").toLowerCase();document.querySelectorAll("#medicineResults .medicine-card").forEach(card=>{card.style.display=card.textContent.toLowerCase().includes(term)?"":"none"})}
function openLabBooking(testId){
  const x=LAB_TESTS.find(y=>y.id===testId);if(!x)return;
  const body=document.getElementById("serviceModalBody");
  openServiceModal(`Book ${x.name}`,`<p class="muted">Choose how and when you want the sample collected.</p><div class="form-grid"><div class="full"><label class="form-label">Collection type *</label><div class="mini-grid"><button class="payment-option selected" id="labHome"><b>Home collection</b><br><span class="muted">A collector visits your address.</span></button><button class="payment-option" id="labWalk"><b>Walk-in lab</b><br><span class="muted">Visit the selected laboratory.</span></button></div></div><div><label class="form-label">Selected date *</label><input id="labDate" class="input" type="date" min="${today()}" value="${today()}"></div><div><label class="form-label">Timings *</label><select id="labTime" class="input"><option>7:00 AM – 8:00 AM</option><option>8:00 AM – 9:00 AM</option><option>9:00 AM – 10:00 AM</option><option>10:00 AM – 11:00 AM</option><option>4:00 PM – 5:00 PM</option><option>5:00 PM – 6:00 PM</option></select></div><div><label class="form-label">Place / laboratory</label><select id="labPlace" class="input">${HOSPITALS.map(h=>`<option value="${h.id}" ${h.id===state.selectedHospital?"selected":""}>${esc(h.name)} · ${esc(h.area)}</option>`).join("")}</select></div><div class="full" id="labAddressWrap"><label class="form-label">Collection address *</label><textarea id="labAddress" class="input profile-textarea" placeholder="House number, street, area, city, PIN"></textarea></div></div><div class="summary"><b>Price details</b><div class="price-line"><span>${esc(x.name)}</span><b>${money(x.price)}</b></div><div class="price-line" id="labCollectionFeeLine"><span>Home collection fee</span><b>${money(100)}</b></div><hr><div class="price-line"><b>Total</b><b id="labTotal">${money(x.price+100)}</b></div></div><div class="actions"><button class="btn" id="labCancel">Cancel</button><button class="btn primary" id="labContinue">Continue to payment →</button></div>`);
  let home=true;
  const update=()=>{document.getElementById("labHome").classList.toggle("selected",home);document.getElementById("labWalk").classList.toggle("selected",!home);document.getElementById("labAddressWrap").style.display=home?"block":"none";document.getElementById("labCollectionFeeLine").style.display=home?"flex":"none";document.getElementById("labTotal").textContent=money(x.price+(home?100:0))};
  document.getElementById("labHome").onclick=()=>{home=true;update()};document.getElementById("labWalk").onclick=()=>{home=false;update()};
  document.getElementById("labCancel").onclick=()=>document.getElementById("serviceModal").classList.remove("show");
  document.getElementById("labContinue").onclick=()=>{const date=document.getElementById("labDate").value,time=document.getElementById("labTime").value,address=document.getElementById("labAddress").value.trim();if(!date)return toast("Choose a collection date");if(home&&!address)return toast("Collection address is required for home collection");const place=HOSPITALS.find(h=>h.id===document.getElementById("labPlace").value);const total=x.price+(home?100:0);body.innerHTML=`<h3>Payment</h3><p class="muted">${esc(x.name)} · ${home?"Home collection":"Walk-in lab"} · ${fmtDate(date)} · ${esc(time)}</p><div class="summary"><div class="price-line"><span>Test price</span><b>${money(x.price)}</b></div>${home?`<div class="price-line"><span>Home collection</span><b>${money(100)}</b></div>`:""}<hr><div class="price-line"><b>Total</b><b>${money(total)}</b></div></div><div class="mini-grid">${["UPI / Demo","Card / Demo","Cash on collection"].map((m,i)=>`<button class="payment-option ${i===0?"selected":""}" data-labpay="${m}"><b>${m}</b><br><span class="muted">Demo payment option</span></button>`).join("")}</div><div class="actions"><button class="btn" id="labBack">← Back</button><button class="btn primary" id="labPay">Confirm booking</button></div>`;let pay="UPI / Demo";body.querySelectorAll("[data-labpay]").forEach(b=>b.onclick=()=>{pay=b.dataset.labpay;body.querySelectorAll("[data-labpay]").forEach(z=>z.classList.remove("selected"));b.classList.add("selected")});document.getElementById("labBack").onclick=()=>openLabBooking(testId);document.getElementById("labPay").onclick=()=>{const order={id:`LAB-${Date.now()}`,testId:x.id,name:x.name,price:x.price,collectionType:home?"Home collection":"Walk-in lab",date,time,place:place?.name||state.settings.location,address:home?address:"",collectionFee:home?100:0,total,paymentMethod:pay,paymentStatus:pay==="Cash on collection"?"PAY AT COLLECTION":"PAID (demo)",status:"booked"};state.labOrders.push(order);state.labs=state.labOrders;save();body.innerHTML=`<div id="labReceipt" class="bill"><div style="font-size:2rem;font-weight:800;color:#168d76">MediBook</div><h3>Lab Test Booking Receipt</h3><hr><p><b>Booking ID:</b> ${esc(order.id)}</p><p><b>Test:</b> ${esc(order.name)}<br><b>Collection:</b> ${esc(order.collectionType)}<br><b>Date:</b> ${fmtDate(order.date)}<br><b>Time:</b> ${esc(order.time)}<br><b>Place:</b> ${esc(order.place)}${order.address?`<br><b>Collection address:</b> ${esc(order.address)}`:""}</p><hr><p><b>Payment:</b> ${esc(order.paymentMethod)} · ${esc(order.paymentStatus)}</p><h2>${money(order.total)}</h2></div><div class="actions"><button class="btn" id="labDone">Back to services</button></div>`;document.getElementById("labDone").onclick=()=>{document.getElementById("serviceModal").classList.remove("show");showView("services");renderServices()};toast("🧪 Lab appointment booked")}};
}
function openMedicineOrder(medId){
  const x=state.medicineCatalog.find(y=>y.id===medId);if(!x)return;
  const panel=document.getElementById("medicineOrderPanel");if(!panel)return;
  const q=Number(document.getElementById(`qty-${x.id}`)?.value||1);let qty=q;
  panel.innerHTML=`<div class="card"><div class="section-head"><div><div class="eyebrow">Medicine order</div><h3>${esc(x.name)}</h3><p class="muted">${esc(x.pack)} · ${money(x.price)} each</p></div><button class="btn" id="closeMedOrder">Close</button></div><div class="form-grid"><div><label class="form-label">Quantity</label><input id="orderQty" class="input" type="number" min="1" max="20" value="${qty}"></div><div><label class="form-label">Delivery option</label><select id="deliveryOption" class="input"><option>Home delivery</option><option>Pickup</option></select></div><div class="full"><label class="form-label">Delivery address *</label><textarea id="deliveryAddress" class="input profile-textarea" placeholder="House number, street, area, city, PIN">${esc(state.profile?.address||"")}</textarea></div></div><div class="summary"><b>Price details</b><div class="price-line"><span>${esc(x.name)} × <span id="orderQtyLabel">${qty}</span></span><b id="medSubtotal">${money(x.price*qty)}</b></div><div class="price-line"><span>Delivery</span><b id="deliveryFee">${money(50)}</b></div><hr><div class="price-line"><b>Total</b><b id="medTotal">${money(x.price*qty+50)}</b></div></div><h4>Payment</h4><div class="mini-grid">${["Cash on Delivery","UPI / Demo","Card / Demo"].map((m,i)=>`<button class="payment-option ${i===0?"selected":""}" data-medpay="${m}"><b>${m}</b><br><span class="muted">Demo payment option</span></button>`).join("")}</div><div class="actions"><button class="btn" id="cancelMedOrder">Cancel</button><button class="btn primary" id="placeMedOrder">Place order</button></div></div>`;
  let pay="Cash on Delivery";
  const update=()=>{qty=Math.max(1,Math.min(20,Number(document.getElementById("orderQty").value)||1));document.getElementById("orderQty").value=qty;document.getElementById("orderQtyLabel").textContent=qty;document.getElementById("medSubtotal").textContent=money(x.price*qty);const delivery=document.getElementById("deliveryOption").value==="Pickup"?0:50;document.getElementById("deliveryFee").textContent=money(delivery);document.getElementById("medTotal").textContent=money(x.price*qty+delivery)};
  document.getElementById("orderQty").oninput=update;document.getElementById("deliveryOption").onchange=update;document.getElementById("closeMedOrder").onclick=()=>panel.innerHTML="";document.getElementById("cancelMedOrder").onclick=()=>panel.innerHTML="";
  panel.querySelectorAll("[data-medpay]").forEach(b=>b.onclick=()=>{pay=b.dataset.medpay;panel.querySelectorAll("[data-medpay]").forEach(z=>z.classList.remove("selected"));b.classList.add("selected")});
  document.getElementById("placeMedOrder").onclick=()=>{const address=document.getElementById("deliveryAddress").value.trim(),delivery=document.getElementById("deliveryOption").value;if(delivery==="Home delivery"&&!address)return toast("Delivery address is required");update();const total=x.price*qty+(delivery==="Pickup"?0:50);const order={id:`MED-${Date.now()}`,medicineId:x.id,name:x.name,qty,unitPrice:x.price,price:x.price*qty,deliveryOption:delivery,deliveryAddress:delivery==="Pickup"?"":address,deliveryFee:delivery==="Pickup"?0:50,total,paymentMethod:pay,paymentStatus:pay==="Cash on Delivery"?"PAY ON DELIVERY":"PAID (demo)",date:today(),status:"ordered"};state.medicines.push(order);save();panel.innerHTML=`<div class="card"><div id="medicineReceipt" class="bill"><div style="font-size:2rem;font-weight:800;color:#168d76">MediBook</div><h3>Medicine Order Receipt</h3><hr><p><b>Order ID:</b> ${esc(order.id)}</p><p><b>Medicine:</b> ${esc(order.name)}<br><b>Quantity:</b> ${order.qty}<br><b>Delivery:</b> ${esc(order.deliveryOption)}${order.deliveryAddress?`<br><b>Address:</b> ${esc(order.deliveryAddress)}`:""}</p><hr><p><b>Payment:</b> ${esc(order.paymentMethod)} · ${esc(order.paymentStatus)}</p><h2>${money(order.total)}</h2></div><div class="actions"><button class="btn" id="medHome">Back to home</button><button class="btn primary" id="medDone">Done</button></div></div>`;document.getElementById("medHome").onclick=()=>{panel.innerHTML="";showView("dashboard")};document.getElementById("medDone").onclick=()=>{panel.innerHTML="";renderServices()};toast("💊 Medicine order placed")};
}
function renderMedicineManager(){const panel=document.getElementById("medicineManagePanel");if(!panel)return;panel.innerHTML=`<div class="card"><div class="section-head"><div><div class="eyebrow">Medicine inventory</div><h3>Manage available medicines</h3><p class="muted">Change availability and amount for this frontend demo.</p></div><button class="btn" id="closeMedicineManager">Close</button></div><div id="medicineManageRows">${state.medicineCatalog.map(x=>`<div class="medicine-manage-row"><div><b>${esc(x.name)}</b><div class="muted">${esc(x.category)} · ${esc(x.pack)}</div></div><label class="form-label"><input type="checkbox" data-medavailable="${x.id}" ${x.available!==false?"checked":""}> Available</label><input class="input" type="number" min="1" data-medprice="${x.id}" value="${Number(x.price)}" style="max-width:120px"><button class="btn" data-medremove="${x.id}">Remove</button></div>`).join("")}</div><div class="form-grid" style="margin-top:16px"><input id="newMedName" class="input" placeholder="Medicine name"><input id="newMedCategory" class="input" placeholder="Category"><input id="newMedPack" class="input" placeholder="Pack information"><input id="newMedPrice" class="input" type="number" min="1" placeholder="Price"><button class="btn primary full" id="addNewMedicine">Add medicine</button></div></div>`;document.getElementById("closeMedicineManager").onclick=()=>panel.innerHTML="";panel.querySelectorAll("[data-medavailable]").forEach(b=>b.onchange=()=>{const x=state.medicineCatalog.find(y=>y.id===b.dataset.medavailable);x.available=b.checked;save();renderServices();renderMedicineManager()});panel.querySelectorAll("[data-medprice]").forEach(b=>b.onchange=()=>{const x=state.medicineCatalog.find(y=>y.id===b.dataset.medprice);x.price=Math.max(1,Number(b.value)||x.price);save();renderServices();renderMedicineManager()});panel.querySelectorAll("[data-medremove]").forEach(b=>b.onclick=()=>{state.medicineCatalog=state.medicineCatalog.filter(x=>x.id!==b.dataset.medremove);save();renderServices();renderMedicineManager()});document.getElementById("addNewMedicine").onclick=()=>{const name=document.getElementById("newMedName").value.trim(),category=document.getElementById("newMedCategory").value.trim()||"General",pack=document.getElementById("newMedPack").value.trim()||"1 pack",price=Number(document.getElementById("newMedPrice").value);if(!name||!price)return toast("Enter medicine name and price");state.medicineCatalog.push({id:`m-${Date.now()}`,name,category,pack,price,available:true});save();renderServices();renderMedicineManager();toast("Medicine added")}}
function bindServices(){document.querySelectorAll("[data-hospital]").forEach(b=>b.onclick=()=>{state.selectedHospital=b.dataset.hospital;save();renderServices();toast("Hospital selected")});document.querySelectorAll("[data-lab]").forEach(b=>b.onclick=()=>openLabBooking(b.dataset.lab));document.querySelectorAll("[data-med]").forEach(b=>b.onclick=()=>openMedicineOrder(b.dataset.med));document.querySelectorAll("[data-medrem]").forEach(b=>b.onclick=()=>{const x=state.medicineCatalog.find(y=>y.id===b.dataset.medrem),t=prompt(`Set a daily reminder for ${x.name}. Time HH:MM (24-hour):`,`20:00`);if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(t||""))return toast("Use a time like 20:00");state.medicineReminders.push({id:`MR-${Date.now()}`,name:x.name,time:t});save();scheduleMedicineReminder(state.medicineReminders.at(-1));toast("💊 Medicine reminder saved")});document.querySelectorAll("[data-surgery]").forEach(b=>b.onclick=()=>{const x=SURGERIES.find(y=>y.id===b.dataset.surgery);openServiceModal(`Plan ${x.name}`,`<p>${esc(x.description)}</p><div class="form-grid"><div class="full"><label class="form-label">Preferred hospital</label><select id="surgeryHospital" class="input">${HOSPITALS.map(h=>`<option value="${h.id}">${esc(h.name)}</option>`).join("")}</select></div><div class="full"><label class="form-label">Planning note</label><input id="surgeryNote" class="input" placeholder="e.g. need pre-op tests, preferred month..."></div></div><div class="actions"><button class="btn primary" id="saveSurgery">Save surgery plan</button></div>`);document.getElementById("saveSurgery").onclick=()=>{const h=HOSPITALS.find(y=>y.id===document.getElementById("surgeryHospital").value);state.surgeries.push({id:`SURG-${Date.now()}`,name:x.name,specialty:x.specialty,hospital:h.name,note:document.getElementById("surgeryNote").value,date:today(),status:"planning"});save();document.getElementById("serviceModal").classList.remove("show");toast("🏥 Surgery plan saved locally")}});const ms=document.getElementById("medicineSearch");if(ms)ms.oninput=()=>{window.medicineSearch=ms.value;filterMedicineCards(ms.value)};const clear=document.getElementById("clearMedicineSearch");if(clear)clear.onclick=()=>{window.medicineSearch="";renderServices()};const manage=document.getElementById("manageMedicines");if(manage)manage.onclick=renderMedicineManager}
function renderLifecycle(){const box=document.getElementById("caseList");if(!box)return;box.innerHTML=state.cases.length?state.cases.map(c=>`<article class="card"><div class="section-head"><div><div class="eyebrow">Case: ${esc(c.title)}</div><h3>${esc(c.patient)} · ${esc(c.specialty)}</h3><p class="muted">Linked doctor: ${esc(c.doctorName)}</p></div><span class="status">${esc(c.stage)}</span></div><div>${c.events.map(e=>`<div class="care-stage"><b>${e.icon} ${esc(e.label)}</b><div class="muted">${esc(e.date)} · ${esc(e.text)}</div></div>`).join("")}</div><div class="actions">${c.stage!=="Recovered"&&c.stage!=="Recurring"?`<button class="btn primary" data-advance-case="${c.id}">Advance lifecycle</button>`:""}${c.stage==="Recovered"?`<button class="btn" data-recur-case="${c.id}">Mark recurring</button>`:""}</div></article>`).join(""):'<div class="card empty">No care cases yet. Create one from the lifecycle dashboard.</div>';document.querySelectorAll("[data-advance-case]").forEach(b=>b.onclick=()=>advanceCase(b.dataset.advanceCase));document.querySelectorAll("[data-recur-case]").forEach(b=>b.onclick=()=>{const c=state.cases.find(x=>x.id===b.dataset.recurCase);c.stage="Recurring";c.events.push({icon:"⚠️",label:"Recurrence Detected",date:today(),text:"Symptoms returned — new consultation linked to previous case."});save();renderLifecycle();toast("Recurrence linked to the case")})}
function createCase(){const completed=state.bookings.find(x=>x.status==="completed")||state.bookings[0];const d=completed?doctorById(completed.doctorId):doctors.find(x=>x.specialty==="General Physician");const title=prompt("Case title:","Seasonal Fever");if(!title)return;const patient=prompt("Patient name:",completed?.patientName||"Aisha R.")||"Demo Patient";const symptoms=prompt("Initial symptoms:",completed?.notes||"fever, fatigue for 2 days")||"symptoms logged at first visit";const c={id:`CASE-${Date.now()}`,title,patient,specialty:d.specialty,doctorName:d.name,stage:"Consultation",events:[{icon:"🩺",label:"Consultation Booked",date:today(),text:`Appointment scheduled with ${d.name} for ${d.specialty}.`},{icon:"📋",label:"Initial Assessment",date:today(),text:`Symptoms logged: ${symptoms}. Condition noted at first visit.`}]};state.cases.push(c);save();renderLifecycle();toast("Care lifecycle case created")}
function advanceCase(id){const c=state.cases.find(x=>x.id===id);const order=["Consultation","Initial Record","Treatment","Follow-up","Recovered"];const i=order.indexOf(c.stage);if(i<0||i===order.length-1)return;const next=order[i+1];const text={"Initial Record":"Symptoms and first-visit assessment connected to this case.","Treatment":"Diagnosis and prescription/advice recorded.","Follow-up":"Recovery check-in booked and linked to the same case.","Recovered":"Condition resolved. Case marked complete."}[next];const icon={"Initial Record":"📋","Treatment":"💊","Follow-up":"🔁","Recovered":"✅"}[next];c.stage=next;c.events.push({icon,label:{"Initial Record":"Initial Assessment","Treatment":"Treatment Prescribed","Follow-up":"Follow-up Scheduled","Recovered":"Recovered"}[next],date:today(),text});save();renderLifecycle();toast(`Lifecycle moved to ${next}`)}
function openServiceModal(title,body){document.getElementById("serviceModalTitle").textContent=title;document.getElementById("serviceModalBody").innerHTML=body;document.getElementById("serviceModal").classList.add("show");document.querySelectorAll("[data-modal-book]").forEach(b=>b.onclick=()=>{document.getElementById("serviceModal").classList.remove("show");openBooking(b.dataset.modalBook)})}
function applySettings(){document.body.classList.toggle("light",state.settings.theme==="light");document.getElementById("themeSwitch").classList.toggle("on",state.settings.theme==="dark");document.getElementById("compactSwitch").classList.toggle("on",state.settings.compact);document.getElementById("soundSwitch").classList.toggle("on",state.settings.sound);document.getElementById("themeBtn").textContent=state.settings.theme==="dark"?"☼":"☾";document.body.style.setProperty("--radius",state.settings.compact?"17px":"24px");document.getElementById("locationSelect").value=state.settings.location}
function renderProfile(){const p=state.profile||{};const ids=["Name","Dob","Gender","Blood","Phone","Email","Address","City","State","Pin","Allergies","Conditions","EmergencyName","EmergencyRelation","EmergencyPhone","Insurance","Policy"];const keys={Name:"name",Dob:"dob",Gender:"gender",Blood:"blood",Phone:"phone",Email:"email",Address:"address",City:"city",State:"state",Pin:"pin",Allergies:"allergies",Conditions:"conditions",EmergencyName:"emergencyName",EmergencyRelation:"emergencyRelation",EmergencyPhone:"emergencyPhone",Insurance:"insurance",Policy:"policy"};ids.forEach(k=>{const el=document.getElementById("profile"+k);if(el)el.value=p[keys[k]]||""});const required=[p.name,p.phone,p.email,p.dob,p.gender,p.address,p.city,p.state,p.pin,p.blood,p.emergencyName,p.emergencyPhone];const complete=Math.round(required.filter(Boolean).length/required.length*100);const badge=document.getElementById("profileCompletion");if(badge)badge.textContent=`${complete}% complete`;const list=document.getElementById("profileHandoverList");const bookings=state.bookings.filter(a=>a.patientName);list.innerHTML=bookings.length?bookings.slice(0,6).map(a=>{const d=doctorById(a.doctorId);return `<div class="card appointment profile-handover"><div><b>${esc(a.patientName)}</b><div class="muted">${esc(d.specialty)} • ${fmtDate(a.date)} • ${esc(a.status)}</div></div><button class="btn" data-handover="${a.id}">View handover summary</button></div>`}).join(""):'<div class="empty">No accepted appointment history yet.</div>';list.querySelectorAll("[data-handover]").forEach(b=>b.onclick=()=>openHandover(b.dataset.handover))}
function saveProfile(){const fields={name:"profileName",dob:"profileDob",gender:"profileGender",blood:"profileBlood",phone:"profilePhone",email:"profileEmail",address:"profileAddress",city:"profileCity",state:"profileState",pin:"profilePin",allergies:"profileAllergies",conditions:"profileConditions",emergencyName:"profileEmergencyName",emergencyRelation:"profileEmergencyRelation",emergencyPhone:"profileEmergencyPhone",insurance:"profileInsurance",policy:"profilePolicy"};const next={};for(const [k,id] of Object.entries(fields))next[k]=document.getElementById(id)?.value.trim()||"";if(next.phone&&!/^\d{10}$/.test(next.phone))return toast("Phone must be exactly 10 digits");if(next.emergencyPhone&&!/^\d{10}$/.test(next.emergencyPhone))return toast("Emergency phone must be exactly 10 digits");if(next.pin&&!/^\d{6}$/.test(next.pin))return toast("PIN code must be 6 digits");state.profile=next;save();renderProfile();toast("Profile saved locally")}
function renderAll(){renderSpecialties("homeSpecialties");renderSpecialties("doctorSpecialties");renderDoctors();renderAppointments();renderRecords();renderServices();renderLifecycle();renderProfile();applySettings()}
document.addEventListener("click",e=>{const b=e.target.closest("[data-view]");if(b){e.preventDefault();showView(b.dataset.view)}const c=e.target.closest("[data-specialty]");if(c){activeSpecialty=c.dataset.specialty;renderAll();showView("doctors")}});
document.getElementById("search").oninput=renderDoctors;document.getElementById("favFilter").onclick=()=>{favOnly=!favOnly;document.getElementById("favFilter").textContent=favOnly?"♥ Favorites only":"♡ Favorites only";renderDoctors};
document.getElementById("suggestBtn").onclick=()=>{const s=document.getElementById("symptomInput").value.toLowerCase();let spec="General Physician";if(["chest","heart","palpitation","blood pressure","cholesterol"].some(x=>s.includes(x)))spec="Cardiology";else if(["migraine","headache","nerves"].some(x=>s.includes(x)))spec="Neurology";else if(["joint","fracture","knee","back pain","spine"].some(x=>s.includes(x)))spec="Orthopedics";else if(["child","baby","vaccination","growth"].some(x=>s.includes(x)))spec="Pediatrics";else if(["skin","rash","acne","itch","hair loss"].some(x=>s.includes(x)))spec="Dermatology";else if(["tooth","cavity","gums","root canal"].some(x=>s.includes(x)))spec="Dentistry";document.getElementById("suggestion").innerHTML=`<div class="summary">Based on those keywords, explore <b style="color:var(--primary)">${esc(spec)}</b>. <button class="btn" data-specialty="${esc(spec)}">View specialists →</button></div>`};
document.getElementById("closeServiceModal").onclick=()=>document.getElementById("serviceModal").classList.remove("show");document.getElementById("saveProfile").onclick=saveProfile;document.getElementById("profileDoctorUnavailable").onclick=openDoctorUnavailable;
document.getElementById("themeBtn").onclick=()=>{state.settings.theme=state.settings.theme==="dark"?"light":"dark";save();applySettings()};document.getElementById("themeSwitch").onclick=()=>{state.settings.theme=state.settings.theme==="dark"?"light":"dark";save();applySettings()};document.getElementById("compactSwitch").onclick=()=>{state.settings.compact=!state.settings.compact;save();applySettings()};document.getElementById("soundSwitch").onclick=()=>{state.settings.sound=!state.settings.sound;save();applySettings()};document.getElementById("resetDemo").onclick=()=>{if(confirm("Reset all MediBook data?")){localStorage.removeItem(KEY);location.reload()}};
document.getElementById("locationSelect").onchange=e=>{state.settings.location=e.target.value;state.selectedHospital=hospitalForLocation(e.target.value);save();renderServices();toast(`📍 ${e.target.value} selected · default hospital updated`)};document.getElementById("newCase").onclick=createCase;
const cursor=document.querySelector(".cursor");document.addEventListener("mousemove",e=>{if(window.gsap)gsap.to(cursor,{x:e.clientX,y:e.clientY,duration:.12,ease:"power2.out"})});document.addEventListener("mouseover",e=>{if(e.target.closest("button,a,input,.card"))cursor.classList.add("active")});document.addEventListener("mouseout",e=>{if(e.target.closest("button,a,input,.card"))cursor.classList.remove("active")});document.addEventListener("mousemove",e=>{const b=e.target.closest(".magnetic");if(!b||!window.gsap)return;const r=b.getBoundingClientRect(),x=e.clientX-(r.left+r.width/2),y=e.clientY-(r.top+r.height/2);if(Math.hypot(x,y)<90)gsap.to(b,{x:x*.14,y:y*.14,duration:.25});else gsap.to(b,{x:0,y:0,duration:.35})});
window.addEventListener("load",()=>{renderAll();state.bookings.filter(x=>x.status==="confirmed").forEach(scheduleAppointmentReminder);state.medicineReminders.forEach(scheduleMedicineReminder);setTimeout(()=>{const o=document.getElementById("onboarding");if(!o)return;if(state.onboarded){o.remove();return}state.onboarded=true;save();if(window.gsap){gsap.to(o,{opacity:0,duration:.55,onComplete:()=>o.remove()})}else{o.style.transition="opacity .25s ease";o.style.opacity="0";setTimeout(()=>o.remove(),260)}},1250);if(window.gsap&&window.ScrollTrigger){gsap.registerPlugin(ScrollTrigger);gsap.utils.toArray(".section").forEach(el=>gsap.from(el,{scrollTrigger:{trigger:el,start:"top 88%"},opacity:0,y:25,duration:.7}))}});
